/**
 * Test fixtures for price/odds parsing
 * Tests various price formats and special price keywords
 */

import { TestCase } from './types';

export const priceParsingTestCases: TestCase[] = [
  // Note: 'ev' test moved from parsers-test-cases.ts
  {
    description: 'Price "ev" converts to +100',
    input: 'IW LAA TT o3.5 @ ev',
    expectedChatType: 'order',
    expectedContractType: 'TotalPointsContestant',
    expectedPrice: 100,
    expectedTeam1: 'LAA',
    expectedLine: 3.5,
    expectedIsOver: true,
    expectedPeriod: {PeriodTypeCode:'M',PeriodNumber:0},
  },
  {
    description: 'Parse positive odds',
    input: 'IW Athletics @ +145',
    expectedChatType: 'order',
    expectedContractType: 'HandicapContestantML',
    expectedPrice: 145,
    expectedTeam1: 'Athletics',
    expectedPeriod: { PeriodTypeCode: 'M', PeriodNumber: 0 },
    expectedTiesLose: false
  },
  {
    description: 'Parse negative odds',
    input: 'IW LAA TT o3.5 @ -115',
    expectedChatType: 'order',
    expectedContractType: 'TotalPointsContestant',
    expectedPrice: -115,
    expectedTeam1: 'LAA',
    expectedLine: 3.5,
    expectedIsOver: true,
    expectedPeriod: { PeriodTypeCode: 'M', PeriodNumber: 0 }
  },
  {
    description: 'Parse decimal odds',
    input: 'YG CIN first team to score @ -109.8 = $265',
    expectedChatType: 'fill',
    expectedContractType: 'PropYN',
    expectedPrice: -109.8,
    expectedSize: 265,
    expectedTeam1: 'CIN',
    expectedProp: 'FirstToScore',
    expectedIsYes: true,
    expectedPeriod: { PeriodTypeCode: 'M', PeriodNumber: 0 }
  },
  
  {
    description: 'Convert "even" to +100',
    input: 'IW LAA TT o3.5 @ even',
    expectedChatType: 'order',
    expectedContractType: 'TotalPointsContestant',
    expectedPrice: 100,
    expectedTeam1: 'LAA',
    expectedLine: 3.5,
    expectedIsOver: true,
    expectedPeriod: { PeriodTypeCode: 'M', PeriodNumber: 0 }
  },
  {
    description: 'Default to -110 when missing in k-notation',
    input: 'YG 872 Athletics @ 4k',
    expectedChatType: 'fill',
    expectedContractType: 'HandicapContestantML',
    expectedPrice: -110,
    expectedSize: 4000,
    expectedRotationNumber: 872,
    expectedTeam1: 'Athletics',
    expectedPeriod: { PeriodTypeCode: 'M', PeriodNumber: 0 },
    expectedTiesLose: false
  },
  // Price words — even / ev / pk / pick / pick'em — are +100 wherever a
  // numeric price is accepted: after "@", standalone, or glued to a total.
  {
    description: 'standalone "even" after a total is the price +100',
    input: 'YG Phillies u4.5 even = 1.0',
    expectedChatType: 'fill',
    expectedContractType: 'TotalPoints',
    expectedPrice: 100,
    expectedSize: 1000,
    expectedRisk: 1000,
    expectedToWin: 1000,
    expectedTeam1: 'Phillies',
    expectedLine: 4.5,
    expectedIsOver: false,
    expectedPeriod: {PeriodTypeCode:'M',PeriodNumber:0},
  },
  {
    description: 'standalone "EV" (any case) after a moneyline contestant is the price +100',
    input: 'YG Phillies EV = 1.0',
    expectedChatType: 'fill',
    expectedContractType: 'HandicapContestantML',
    expectedPrice: 100,
    expectedSize: 1000,
    expectedTeam1: 'Phillies',
    expectedPeriod: {PeriodTypeCode:'M',PeriodNumber:0},
  },
  {
    description: 'standalone "pk" after a spread line is the price +100',
    input: 'IW Phillies -1.5 pk',
    expectedChatType: 'order',
    expectedContractType: 'HandicapContestantLine',
    expectedPrice: 100,
    expectedTeam1: 'Phillies',
    expectedLine: -1.5,
    expectedPeriod: {PeriodTypeCode:'M',PeriodNumber:0},
  },
  {
    description: '"pick" after @ is the price +100',
    input: 'IW Phillies/Braves o8.5 @ PICK',
    expectedChatType: 'order',
    expectedContractType: 'TotalPoints',
    expectedPrice: 100,
    expectedTeam1: 'Phillies',
    expectedTeam2: 'Braves',
    expectedLine: 8.5,
    expectedIsOver: true,
    expectedPeriod: {PeriodTypeCode:'M',PeriodNumber:0},
  },
  {
    description: "standalone \"pick'em\" is the price +100",
    input: "IW Phillies/Braves u8.5 pick'em",
    expectedChatType: 'order',
    expectedContractType: 'TotalPoints',
    expectedPrice: 100,
    expectedTeam1: 'Phillies',
    expectedTeam2: 'Braves',
    expectedLine: 8.5,
    expectedIsOver: false,
    expectedPeriod: {PeriodTypeCode:'M',PeriodNumber:0},
  },
  {
    description: 'price word glued to a total line ("u4.5ev") is the price +100',
    input: 'YG Phillies F5 u4.5ev = 1.0',
    expectedChatType: 'fill',
    expectedContractType: 'TotalPoints',
    expectedPrice: 100,
    expectedSize: 1000,
    expectedTeam1: 'Phillies',
    expectedLine: 4.5,
    expectedIsOver: false,
    expectedPeriod: {PeriodTypeCode:'H',PeriodNumber:1},
  },
  {
    description: 'price word after a period-first team total is the price +100',
    input: 'IW h1 Phillies TT u2.5 even',
    expectedChatType: 'order',
    expectedContractType: 'TotalPointsContestant',
    expectedPrice: 100,
    expectedTeam1: 'Phillies',
    expectedLine: 2.5,
    expectedIsOver: false,
    expectedPeriod: {PeriodTypeCode:'H',PeriodNumber:1},
  },
];